changeSet.sql:
ALTER TABLE client_payments ADD COLUMN IF NOT EXISTS legacy_tranche_id BIGINT; ALTER TABLE client_payments ADD COLUMN IF NOT EXISTS legacy_proforma_id BIGINT;
INSERT INTO client_payments (project_id, kind, status, due_date, amount_gross, paid_gross, currency, note, created_date, created_by, updated_date, updated_by, legacy_tranche_id) SELECT s.project_id, 'WORKS', t.status, t.due_date, t.amount_gross, t.paid_gross, COALESCE(s.currency, 'PLN'), NULL, t.created_date, t.created_by, t.updated_date, t.updated_by, t.id FROM payment_tranches t JOIN payment_schedules s ON s.id = t.schedule_id WHERE t.client_payment_id IS NULL ORDER BY t.id;
INSERT INTO client_payments (project_id, kind, status, due_date, amount_gross, paid_gross, currency, note, created_date, created_by, updated_date, updated_by, legacy_proforma_id) SELECT p.project_id, 'MATERIALS', p.status, p.due_date, p.total_gross, p.paid_gross, p.currency, p.note, p.created_date, p.created_by, p.updated_date, p.updated_by, p.id FROM client_proformas p WHERE p.client_payment_id IS NULL ORDER BY p.id;
UPDATE payment_tranches t SET client_payment_id = cp.id FROM client_payments cp WHERE cp.legacy_tranche_id = t.id AND t.client_payment_id IS NULL;
UPDATE client_proformas p SET client_payment_id = cp.id FROM client_payments cp WHERE cp.legacy_proforma_id = p.id AND p.client_payment_id IS NULL;
ALTER TABLE client_payments DROP COLUMN legacy_tranche_id; ALTER TABLE client_payments DROP COLUMN legacy_proforma_id;

