changeSet.sql:
ALTER TABLE payment_tranches ALTER COLUMN client_payment_id SET NOT NULL;
ALTER TABLE client_proformas ALTER COLUMN client_payment_id SET NOT NULL;

ALTER TABLE payment_tranches
    ADD CONSTRAINT uq_payment_tranches_client_payment UNIQUE (client_payment_id);
ALTER TABLE payment_tranches
    ADD CONSTRAINT fk_payment_tranches_client_payment
    FOREIGN KEY (client_payment_id) REFERENCES client_payments (id) ON DELETE CASCADE;

ALTER TABLE client_proformas
    ADD CONSTRAINT uq_client_proformas_client_payment UNIQUE (client_payment_id);
ALTER TABLE client_proformas
    ADD CONSTRAINT fk_client_proformas_client_payment
    FOREIGN KEY (client_payment_id) REFERENCES client_payments (id) ON DELETE CASCADE;

ALTER TABLE client_payments
    ADD CONSTRAINT ck_client_payments_kind CHECK (kind IN ('WORKS', 'MATERIALS'));
ALTER TABLE client_payments
    ADD CONSTRAINT ck_client_payments_status CHECK (
        (kind = 'WORKS' AND status IN ('PENDING', 'DUE', 'PARTIALLY_PAID', 'PAID', 'OVERDUE'))
        OR (kind = 'MATERIALS' AND status IN ('DRAFT', 'ISSUED', 'PARTIALLY_PAID', 'PAID', 'CANCELLED')));
ALTER TABLE client_payments
    ADD CONSTRAINT ck_client_payments_amounts CHECK (
        amount_gross >= 0 AND paid_gross >= 0 AND (kind <> 'WORKS' OR amount_gross > 0));

-- Deprecated common columns: no longer written, so they must not require a value.
ALTER TABLE payment_tranches ALTER COLUMN due_date DROP NOT NULL;
ALTER TABLE payment_tranches ALTER COLUMN amount_gross DROP NOT NULL;
ALTER TABLE payment_tranches ALTER COLUMN paid_gross DROP NOT NULL;
ALTER TABLE payment_tranches ALTER COLUMN status DROP NOT NULL;
ALTER TABLE client_proformas ALTER COLUMN status DROP NOT NULL;
ALTER TABLE client_proformas ALTER COLUMN currency DROP NOT NULL;
ALTER TABLE client_proformas ALTER COLUMN total_gross DROP NOT NULL;
ALTER TABLE client_proformas ALTER COLUMN paid_gross DROP NOT NULL;

